<template><view class="appeal"><view class="card"><text class="heading">人工申诉找回账号</text><text class="hint">适用于忘记原商城账号密码、无法验证原账号绑定微信的情况。请提供账号归属线索，客服收集资料、管理员核实后，才会把原账号密码重置为你在这里设置的新密码；不能只凭姓名或电话找回。</text><template v-if="!key"><input v-model="username" placeholder="原商城登录账号" maxlength="40"/><input v-model="contact" placeholder="可联系您的方式，如手机号或微信号" maxlength="200"/><textarea v-model="evidence" placeholder="填写原订单、使用时间或企业授权等归属线索，至少20字。不要填写原密码、完整证件号。" maxlength="2000"/><text class="hint count">已填写 {{evidence.trim().length}} 字</text><input v-model="password" password placeholder="核实通过后使用的新密码（8至64位）" maxlength="64"/><input v-model="again" password placeholder="再次输入新密码" maxlength="64"/><button class="ui-button" :disabled="busy" @click="submit">{{busy?'正在提交…':'提交申诉'}}</button></template><template v-else><view class="key-box"><text class="hint">查询凭证已保存在当前设备。换手机或清除数据后需要用它查询进度，请复制留存：</text><text selectable user-select class="key">{{key}}</text><button class="ui-button" :disabled="copying" @click="copy">{{copying?'正在复制…':'复制查询凭证'}}</button></view><button class="ui-button" :disabled="busy" @click="refresh">{{busy?'正在查询…':'刷新处理进度'}}</button><view v-if="status" class="status">当前进度：{{states[status.status]||'处理中'}}<view v-if="status.note" class="note">{{status.note}}</view></view><template v-if="status&&['pending','more'].includes(status.status)"><textarea v-model="evidence" placeholder="补充完整归属依据，至少20字，将替换原提交内容" maxlength="2000"/><button class="ui-button" :disabled="busy" @click="supplement">{{busy?'正在提交…':'补充资料'}}</button></template><template v-if="status?.status==='approved'"><text class="hint">请到登录页点“已有商城账号？首次绑定微信”，填写原账号和申诉时设置的新密码完成登录。</text><button class="ui-button" @click="go('login')">去登录并绑定微信</button></template></template></view><view class="card"><input v-model="savedKey" placeholder="换设备可粘贴已保存的查询凭证"/><button class="ui-button" :disabled="busy||!savedKey.trim()" @click="restore">查询已有申诉</button><button class="ui-button" v-if="key" :disabled="busy" @click="newAppeal">提交另一份申诉</button></view><CopyFallback :value="copyFallback" :busy="copying" @retry="copy" @close="copyFallback=''"/></view></template>
<script>
import CopyFallback from './CopyFallback.vue'
import {copyText} from '../services/clipboard'
import {request,notify,go} from '../services/shop'
export default {components:{CopyFallback},data(){return{username:'',contact:'',evidence:'',password:'',again:'',key:uni.getStorageSync('shop-appeal-key')||'',savedKey:'',status:null,busy:false,copying:false,copyFallback:'',states:{pending:'待核实',more:'需要补充资料',approved:'已重置，请用新密码登录',rejected:'未通过，请查看说明'}}},mounted(){if(this.key)this.refresh()},methods:{go,async act(fn){if(this.busy)return;this.busy=true;try{await fn()}catch(e){notify(e)}finally{this.busy=false}},check(){const name=this.username.trim(),contact=this.contact.trim(),evidence=this.evidence.trim();if(!/^[A-Za-z0-9_]{3,40}$/.test(name))return '请填写原商城登录账号（字母、数字或下划线）';if(contact.length<5)return '请填写可联系您的方式，至少5个字';if(evidence.length<20)return '归属线索至少填写20字，目前'+evidence.length+'字';if(this.password.length<8)return '新密码至少8位';if(this.password!==this.again)return '两次密码不一致';return ''},submit(){this.act(async()=>{const problem=this.check();if(problem)throw Error(problem);const r=await request('/account-appeals','POST',{username:this.username.trim(),contact:this.contact.trim(),evidence:this.evidence.trim(),password:this.password});this.key=r.key;uni.setStorageSync('shop-appeal-key',r.key);this.password='';this.again='';this.evidence='';this.status={status:r.status,note:'申诉已提交，核实完成后可在这里查看结果。'}})},refresh(){this.act(async()=>{this.status=await request('/account-appeals/status','POST',{key:this.key})})},supplement(){this.act(async()=>{const evidence=this.evidence.trim();if(evidence.length<20)throw Error('补充资料至少填写20字，目前'+evidence.length+'字');await request('/account-appeals/supplement','POST',{key:this.key,evidence});this.evidence='';this.status=await request('/account-appeals/status','POST',{key:this.key});notify('补充资料已提交')})},async copy(){if(this.copying)return;this.copying=true;try{await copyText(this.key,{successText:'查询凭证已复制',onFallback:text=>{this.copyFallback=text}})}finally{this.copying=false}},restore(){this.act(async()=>{const key=this.savedKey.trim(),r=await request('/account-appeals/status','POST',{key});this.key=key;this.status=r;this.savedKey='';uni.setStorageSync('shop-appeal-key',key)})},newAppeal(){if(this.busy)return;this.key='';this.status=null;this.evidence='';this.copyFallback='';uni.removeStorageSync('shop-appeal-key')}}}
</script><style scoped>
@import '../styles/component-base.css';
.appeal{padding:16px;font-size:16px}.card{background:var(--shop-surface, #fdfeff);padding:16px;border-radius:12px;line-height:1.9;margin-bottom:14px}.heading{font-size:20px;font-weight:bold;display:block}.hint{display:block;font-size:14px;color:var(--shop-ink, #28546c);line-height:1.8}.count{text-align:right;font-size:12px;margin-top:-6px}input,textarea{background:var(--shop-background, #f3f8fb);padding:14px;margin:12px 0;width:auto}textarea{height:160px}button{background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);font-size:16px;margin-top:12px}.key-box{margin:8px 0;padding:14px;background:var(--shop-background, #f3f8fb);border-radius:9px}.key{display:block;margin:8px 0;font-size:14px;line-height:1.7;word-break:break-all;overflow-wrap:anywhere;color:var(--shop-text, #2b424f)}.status{margin-top:14px;padding:12px 14px;background:var(--shop-background, #f3f8fb);border-radius:9px}.note{font-size:14px;color:var(--shop-ink, #28546c)}</style>
